import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines for an empty collaborators object", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
    });
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const cart = new Cart();
      cart.add(productA, 1); // original 1000
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("refreshes each product independently", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1100)
          .mockResolvedValueOnce(2200),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(3300);
    });

    it("throws RangeError for invalid fetched price", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        RangeError,
      );
    });

    it("propagates fetcher rejection", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockRejectedValue(new Error("network error")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "network error",
      );
    });
  });

  describe("inventoryChecker", () => {
    it("proceeds when all items are available", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "out of stock" }),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(1);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: true, availableQuantity: 1 }),
      };
      const cart = new Cart();
      cart.add(productA, 5);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(1);
      }
    });

    it("InventoryError has correct name property", async () => {
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect((e as InventoryError).name).toBe("InventoryError");
      }
    });

    it("first denial wins (stops at first failing item)", async () => {
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: false, reason: "fail A" })
          .mockResolvedValueOnce({ available: true }),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect((e as InventoryError).productId).toBe("a");
      }
      // Should have stopped after the first denial
      expect(checker.check).toHaveBeenCalledTimes(1);
    });
  });

  describe("asyncTaxProvider", () => {
    it("computes tax using async rate", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart();
      cart.add(productA, 1); // subtotal 1000, no discount → taxable 1000
      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(result.totals.taxCents).toBe(100); // 1000 * 0.1
      expect(provider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
      });
      cart.add(productA, 1); // subtotal 1000, discount 200 → taxable 800
      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(result.totals.taxCents).toBe(80);
    });

    it("propagates async tax provider rejection", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(
        cart.checkout({ asyncTaxProvider: provider }),
      ).rejects.toThrow("tax service down");
    });

    it("throws for invalid async rate", async () => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(5.0),
      };
      const cart = new Cart();
      cart.add(productA, 1);
      await expect(
        cart.checkout({ asyncTaxProvider: provider }),
      ).rejects.toThrow(RangeError);
    });
  });

  describe("full composition", () => {
    it("price refresh + inventory check + async tax + shipping", async () => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(productA, 2);
      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });
      // refreshed subtotal: 2000 * 2 = 4000
      // discount: 10% of 4000 = 400
      // discountedSubtotal: 3600
      // tax: 3600 * 0.1 = 360
      // shipping: 500 (flat)
      // total: 3600 + 360 + 500 = 4460
      expect(result.totals.subtotalCents).toBe(4000);
      expect(result.totals.discountCents).toBe(400);
      expect(result.totals.taxCents).toBe(360);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(4460);
    });
  });
});

