import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects percent below 0", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent above 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0 percent and returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100 percent and returns full subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 9999 with floor rounding", () => {
    const policy = new PercentageDiscountPolicy(10);
    // 9999 * 10 / 100 = 999.9 → floor → 999
    expect(policy.computeDiscountCents(9999)).toBe(999);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-1000)).toBe(0);
  });

  it("computes correctly for a very large subtotal", () => {
    const policy = new PercentageDiscountPolicy(15);
    // 1_000_000 * 15 / 100 = 150_000
    expect(policy.computeDiscountCents(1_000_000)).toBe(150_000);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0 and returns 0", () => {
    const policy = new FixedAmountDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(10000)).toBe(500);
  });

  it("clamps to subtotal when discount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(5000);
    expect(policy.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 1000
        new FixedAmountDiscountPolicy(200), // 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const policies = [
        new PercentageDiscountPolicy(80), // 8000
        new FixedAmountDiscountPolicy(5000), // 5000
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // 8000 + 5000 = 13000 which exceeds 10000 — that's ok, Cart clamps it
      expect(composite.computeDiscountCents(10000)).toBe(13000);
    });

    it("clamps negative child results to 0 before summing", () => {
      const mockPolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [mockPolicy, new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // -100 → clamped to 0, then +200 → 200
      expect(composite.computeDiscountCents(10000)).toBe(200);
    });
  });

  describe("chain mode", () => {
    it("applies each policy to remaining subtotal sequentially", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 → 1000, remaining 9000
        new PercentageDiscountPolicy(10), // 10% of 9000 → 900, remaining 8100
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("stops accumulating once remaining is 0", () => {
      const policies = [
        new PercentageDiscountPolicy(100), // 10000 → remaining 0
        new FixedAmountDiscountPolicy(500), // 0 remaining → 0
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("ordering matters in chain mode", () => {
      const pA = [
        new FixedAmountDiscountPolicy(1000), // remaining 9000
        new PercentageDiscountPolicy(10), // 10% of 9000 = 900
      ];
      const pB = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
        new FixedAmountDiscountPolicy(1000), // 1000
      ];
      const a = new CompositeDiscountPolicy(pA, "chain");
      const b = new CompositeDiscountPolicy(pB, "chain");
      expect(a.computeDiscountCents(10000)).toBe(1900);
      expect(b.computeDiscountCents(10000)).toBe(2000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode", () => {
    const policies = [
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ];
    const composite = new CompositeDiscountPolicy(policies);
    expect(composite.computeDiscountCents(10000)).toBe(300);
  });
});

