toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 regardless of input", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("returns 0 for zero taxable amount", () => {
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  it("rejects defaultRate below 0", () => {
    expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
  });

  it("rejects defaultRate above 1", () => {
    expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
  });

  it("rejects NaN defaultRate", () => {
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("rejects a rate below 0 in the rates map", () => {
    expect(() => new RegionalTaxCalculator({ US: -0.01 })).toThrow(RangeError);
  });

  it("rejects a rate above 1 in the rates map", () => {
    expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
  });

  it("uses the region-specific rate", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 });
    // 10000 * 0.0875 = 875
    expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
  });

  it("falls back to defaultRate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ US: 0.07 }, 0.05);
    // 10000 * 0.05 = 500
    expect(calc.computeTaxCents(10000, "FR")).toBe(500);
  });

  it("uses 0 as default when no defaultRate provided", () => {
    const calc = new RegionalTaxCalculator({ US: 0.07 });
    expect(calc.computeTaxCents(10000, "FR")).toBe(0);
  });

  it("rounds down to nearest cent", () => {
    const calc = new RegionalTaxCalculator({ US: 0.0875 });
    // 9999 * 0.0875 = 874.9125 → floor → 874
    expect(calc.computeTaxCents(9999, "US")).toBe(874);
  });

  it("returns 0 for zero taxable amount", () => {
    const calc = new RegionalTaxCalculator({ US: 0.1 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable amount", () => {
    const calc = new RegionalTaxCalculator({ US: 0.1 });
    expect(calc.computeTaxCents(-1000, "US")).toBe(0);
  });

  it("accepts boundary rate of 0", () => {
    const calc = new RegionalTaxCalculator({ US: 0 });
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("accepts boundary rate of 1", () => {
    const calc = new RegionalTaxCalculator({ US: 1 });
    expect(calc.computeTaxCents(10000, "US")).toBe(10000);
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for zero taxable amount without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable amount without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-500, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("computes tax using the resolved rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 10000 * 0.08 = 800
    expect(await calc.computeTaxCents(10000, "US-CA")).toBe(800);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 9999 * 0.0875 = 874.9125 → 874
    expect(await calc.computeTaxCents(9999, "US")).toBe(874);
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network failure")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(
      "network failure",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 1 },
    ];
    // 200*2 + 500*1 = 900
    expect(totalLineWeightGrams(lines)).toBe(900);
  });

  it("treats undefined weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

