toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines", () => {
    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(9.99)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(799);
    expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(799);
  });

  it("returns 0 when subtotal meets freeOver threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds freeOver threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100)], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal is below freeOver threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100)], 4999)).toBe(500);
  });

  it("accepts 0 flatCents and returns 0", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([makeLine("a", 100)], 1000)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("requires at least one bracket", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 5000)).toBe(0);
  });

  it("returns 0 for zero-weight items", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    expect(calc.computeShippingCents(lines, 100)).toBe(0);
  });

  it("selects the first bracket that the weight fits into", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 400g fits in first bracket
    expect(calc.computeShippingCents([makeLine("a", 400)], 5000)).toBe(300);
  });

  it("selects the correct bracket at boundary (exactly upToGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 500g exactly → first bracket
    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(300);
  });

  it("moves to next bracket when weight exceeds boundary", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 501g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 501)], 5000)).toBe(600);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500)], 5000)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000)], 5000)).toBe(600);
  });

  it("sorts brackets by upToGrams regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 500, costCents: 300 },
    ]);
    // 400g → should match 500g bracket (300 cents)
    expect(calc.computeShippingCents([makeLine("a", 400)], 5000)).toBe(300);
  });

  it("sums weight across multiple lines and quantities", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200*2 + 300*1 = 700g → second bracket
    const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 5000)).toBe(600);
  });
});

